UPDATE rubric SET genre = 'action', criteria = '[{"id":"fidelity","name":"Aderência ao tema","kind":"objective","publicDescription":"Mostre na cena o contexto e as exigências do exercício.","maxScore":150,"bands":[{"id":"missing","min":0,"max":30,"description":"Não é uma cena de ação, ou abandona o tema."},{"id":"thin","min":31,"max":75,"description":"Há movimento, mas falta o lugar, a pressão ou uma exigência central do tema."},{"id":"working","min":76,"max":120,"description":"A cena cumpre o tema. Uma exigência fica só sugerida."},{"id":"strong","min":121,"max":150,"description":"Lugar, pessoas, pressão e exigências do tema estão na cena e mudam o que acontece."}]},{"id":"shape","name":"Movimento com consequência","kind":"objective","publicDescription":"Faça um obstáculo mudar o trajeto ou o plano de alguém.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"As pessoas se deslocam sem espaço e sem consequência."},{"id":"thin","min":41,"max":100,"description":"Há um trajeto, mas o obstáculo não muda o que elas fazem."},{"id":"working","min":101,"max":160,"description":"O espaço atrapalha ou ajuda, e o fim é diferente do começo por causa disso."},{"id":"strong","min":161,"max":200,"description":"Cada trecho do trajeto cobra um custo e empurra a escolha seguinte."}]},{"id":"world","name":"Clareza em velocidade","kind":"objective","publicDescription":"Ajude o leitor a acompanhar quem está onde durante a ação.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"Não dá para saber quem se move, nem para onde."},{"id":"thin","min":41,"max":100,"description":"A geografia aparece em relances e se perde no meio."},{"id":"working","min":101,"max":160,"description":"Dá para seguir a cena, com um trecho em que a posição fica ambígua."},{"id":"strong","min":161,"max":200,"description":"Velocidade e orientação andam juntas. O leitor sente a pressa sem se perder."}]},{"id":"people","name":"Pressão e escolha","kind":"subjective","publicDescription":"Coloque alguém diante de uma escolha que tenha um custo.","maxScore":250,"bands":[{"id":"missing","min":0,"max":50,"description":"Ninguém quer nada específico, ou a pressa é genérica."},{"id":"thin","min":51,"max":125,"description":"O objetivo existe, mas a escolha não custa, ou o custo é anunciado e não mostrado."},{"id":"working","min":126,"max":200,"description":"Há uma escolha com custo, e o sentimento cabe nesta pessoa, mesmo com um trecho ainda genérico."},{"id":"strong","min":201,"max":250,"description":"Desejo, obstáculo e preço ficam visíveis no que a pessoa faz. Dá para entender por que ela continua ou por que para."}]},{"id":"prose","name":"Ritmo","kind":"subjective","publicDescription":"Use frases, pausas e detalhes para dar ritmo ao movimento.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"O andamento é igual do começo ao fim, ou a prosa trava a ação sem ganho."},{"id":"thin","min":41,"max":100,"description":"Há variação ocasional, mas a prosa não responde ao que está acontecendo."},{"id":"working","min":101,"max":160,"description":"O ritmo acompanha a maior parte da cena. Uma passagem importante fica lenta ou apressada demais para o que ela é."},{"id":"strong","min":161,"max":200,"description":"Aceleração, pausa e imagem parecem escolhidas. O tempo da cena está no corpo da frase."}]}]'::jsonb WHERE id = 'rubric_action';

--> statement-breakpoint
UPDATE rubric SET genre = 'fight', criteria = '[{"id":"fidelity","name":"Aderência ao tema","kind":"objective","publicDescription":"Mostre na luta o contexto e as exigências do exercício.","maxScore":150,"bands":[{"id":"missing","min":0,"max":30,"description":"Não há confronto físico, ou a cena troca a luta por outro gênero."},{"id":"thin","min":31,"max":75,"description":"Há briga, mas falta o lugar, quem são as pessoas ou uma exigência central do tema."},{"id":"working","min":76,"max":120,"description":"A luta cumpre o tema. Uma exigência aparece e quase não altera os golpes."},{"id":"strong","min":121,"max":150,"description":"Lugar, pessoas e exigências do tema mudam a maneira como se luta."}]},{"id":"shape","name":"Causa e efeito físico","kind":"objective","publicDescription":"Faça cada golpe ou defesa afetar o gesto seguinte.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"Os corpos se batem sem ordem e sem consequência."},{"id":"thin","min":41,"max":100,"description":"Há uma sequência, mas o corpo no fim está igual ao corpo do começo."},{"id":"working","min":101,"max":160,"description":"Um golpe, um erro ou o cansaço muda o movimento seguinte. Um trecho ainda parece sem peso."},{"id":"strong","min":161,"max":200,"description":"Cada troca deixa um rastro, e o fim da luta só é possível por causa do que veio antes."}]},{"id":"world","name":"Espaço e recursos","kind":"objective","publicDescription":"Use o espaço e os objetos para mudar as possibilidades da luta.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"A briga acontece num vazio, sem chão, distância ou objeto."},{"id":"thin","min":41,"max":100,"description":"O lugar é nomeado, mas não limita nem ajuda ninguém."},{"id":"working","min":101,"max":160,"description":"Pelo menos um elemento do espaço muda o que alguém consegue fazer."},{"id":"strong","min":161,"max":200,"description":"O lugar e o que está à mão conduzem a luta. A geografia continua legível."}]},{"id":"people","name":"O que os corpos protegem","kind":"subjective","publicDescription":"Mostre o que cada pessoa tenta proteger ao lutar.","maxScore":250,"bands":[{"id":"missing","min":0,"max":50,"description":"A briga não tem motivo reconhecível nestas pessoas."},{"id":"thin","min":51,"max":125,"description":"O motivo é declarado numa frase e não aparece nos gestos."},{"id":"working","min":126,"max":200,"description":"O que está em jogo aparece em pelo menos um gesto de proteção, recusa ou risco."},{"id":"strong","min":201,"max":250,"description":"Os golpes, as pausas e o que alguém se recusa a fazer mostram o conflito melhor do que uma explicação."}]},{"id":"prose","name":"Coreografia legível","kind":"subjective","publicDescription":"Deixe claros os movimentos e suas consequências.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"Não dá para visualizar os corpos, ou a prosa só lista golpes."},{"id":"thin","min":41,"max":100,"description":"Alguns gestos são claros e o resto vira sumário de violência."},{"id":"working","min":101,"max":160,"description":"A maior parte da luta se acompanha. Uma troca importante fica confusa ou decorativa."},{"id":"strong","min":161,"max":200,"description":"Imagem, velocidade e pausa deixam a luta legível e específica. O estilo combina com quem está lutando."}]}]'::jsonb WHERE id = 'rubric_fight';

--> statement-breakpoint
UPDATE rubric SET genre = 'romance', criteria = '[{"id":"fidelity","name":"Aderência ao tema","kind":"objective","publicDescription":"Mostre no encontro o contexto e as exigências do exercício.","maxScore":150,"bands":[{"id":"missing","min":0,"max":30,"description":"Não há relação romântica em jogo, ou a cena ignora o contexto do tema."},{"id":"thin","min":31,"max":75,"description":"O tom romântico aparece, mas falta uma exigência central do tema."},{"id":"working","min":76,"max":120,"description":"A cena cumpre o tema. Uma exigência fica decorativa."},{"id":"strong","min":121,"max":150,"description":"O contexto do tema conduz a atenção, o toque e o que fica sem dizer."}]},{"id":"shape","name":"Atenção entre pessoas","kind":"objective","publicDescription":"Mostre a atenção entre as pessoas em gestos e reações.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"As pessoas dividem o espaço sem se notar."},{"id":"thin","min":41,"max":100,"description":"Há olhares ou elogios genéricos, sem um gesto que responda a eles."},{"id":"working","min":101,"max":160,"description":"Um detalhe específico da outra pessoa provoca um gesto, uma fala ou uma retirada."},{"id":"strong","min":161,"max":200,"description":"A atenção é mútua ou claramente desigual, e essa diferença aparece em mais de um momento."}]},{"id":"world","name":"Virada do vínculo","kind":"objective","publicDescription":"Faça a relação mudar durante a cena.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"A relação no fim está igual à relação do começo."},{"id":"thin","min":41,"max":100,"description":"O texto anuncia que algo mudou, sem mostrar a mudança."},{"id":"working","min":101,"max":160,"description":"Há uma virada visível, mas o passo seguinte fica nebuloso."},{"id":"strong","min":161,"max":200,"description":"O leitor vê o que mudou e o que cada pessoa fez para isso acontecer."}]},{"id":"people","name":"Sentimento específico","kind":"subjective","publicDescription":"Dê ao sentimento detalhes próprios dessas pessoas.","maxScore":250,"bands":[{"id":"missing","min":0,"max":50,"description":"O sentimento é um rótulo, sem corpo nem ocasião."},{"id":"thin","min":51,"max":125,"description":"A emoção é reconhecível e poderia pertencer a qualquer casal."},{"id":"working","min":126,"max":200,"description":"Há detalhes destas pessoas, ao lado de uma formulação ainda pronta."},{"id":"strong","min":201,"max":250,"description":"O afeto está nos detalhes e nas escolhas. Tirar os nomes não tornaria a cena intercambiável."}]},{"id":"prose","name":"Intimidade na prosa","kind":"subjective","publicDescription":"Use a prosa para aproximar o leitor da intimidade da cena.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"A prosa resume o sentimento e não deixa o leitor dentro do momento."},{"id":"thin","min":41,"max":100,"description":"Há imagens, mas elas repetem o que o narrador já explicou."},{"id":"working","min":101,"max":160,"description":"A maior parte da intimidade está mostrada. Uma passagem importante é explicada demais."},{"id":"strong","min":161,"max":200,"description":"O que é dito, o que é calado e o andamento da frase criam a intimidade sem um resumo final."}]}]'::jsonb WHERE id = 'rubric_romance';

--> statement-breakpoint
UPDATE rubric SET genre = 'dialogue', criteria = '[{"id":"fidelity","name":"Aderência ao tema","kind":"objective","publicDescription":"Mostre na conversa o contexto e as exigências do exercício.","maxScore":150,"bands":[{"id":"missing","min":0,"max":30,"description":"A cena não é conduzida pelo diálogo, ou ignora o tema."},{"id":"thin","min":31,"max":75,"description":"Há conversa, mas uma exigência central do tema fica de fora."},{"id":"working","min":76,"max":120,"description":"O diálogo cumpre o tema. Uma exigência entra tarde ou de passagem."},{"id":"strong","min":121,"max":150,"description":"Lugar, pessoas e exigências do tema estão dentro da conversa e mudam o que é dito."}]},{"id":"shape","name":"Vozes separáveis","kind":"objective","publicDescription":"Dê a cada pessoa um jeito reconhecível de falar.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"As falas são intercambiáveis."},{"id":"thin","min":41,"max":100,"description":"Uma pessoa tem algum tique, e a outra fala como o narrador."},{"id":"working","min":101,"max":160,"description":"Dá para distinguir as vozes na maior parte da cena, com uma troca em que elas se misturam."},{"id":"strong","min":161,"max":200,"description":"Cada voz carrega um desejo ou um jeito de pensar. A distinção não depende de gíria decorativa."}]},{"id":"world","name":"Subtexto e pressão","kind":"objective","publicDescription":"Faça o que fica por dizer pressionar a conversa.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"Tudo o que importa é dito de frente e resolvido na hora."},{"id":"thin","min":41,"max":100,"description":"Há uma evasiva, mas ela não altera o resto da conversa."},{"id":"working","min":101,"max":160,"description":"Uma fala indireta, uma recusa ou um atraso muda o que vem depois."},{"id":"strong","min":161,"max":200,"description":"A pressão atravessa a cena. O leitor entende mais do que as personagens admitem, e o fim registra isso."}]},{"id":"people","name":"Gente atrás das falas","kind":"subjective","publicDescription":"Mostre desejos e receios por trás das falas.","maxScore":250,"bands":[{"id":"missing","min":0,"max":50,"description":"As falas não revelam o que alguém quer."},{"id":"thin","min":51,"max":125,"description":"O objetivo é anunciado, e as falas seguintes não o perseguem nem o escondem."},{"id":"working","min":126,"max":200,"description":"Dá para inferir o que cada pessoa quer, com um trecho em que uma delas só empurra informação."},{"id":"strong","min":201,"max":250,"description":"As estratégias de fala, inclusive o silêncio e a mentira, combinam com quem está falando."}]},{"id":"prose","name":"Fala que parece fala","kind":"subjective","publicDescription":"Dê às falas um ritmo que caiba nessas pessoas.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"As falas são texto expositivo com aspas."},{"id":"thin","min":41,"max":100,"description":"Há momentos de fala viva e blocos que só informam o leitor."},{"id":"working","min":101,"max":160,"description":"A maior parte soa dita em voz alta. Uma fala importante está arrumada demais para quem a diz."},{"id":"strong","min":161,"max":200,"description":"Ritmo, corte e silêncio parecem orais e específicos. O leitor ouve gente, não um resumo."}]}]'::jsonb WHERE id = 'rubric_dialogue';

--> statement-breakpoint
UPDATE rubric SET genre = 'suspense', criteria = '[{"id":"fidelity","name":"Aderência ao tema","kind":"objective","publicDescription":"Mostre na cena o contexto e as exigências do exercício.","maxScore":150,"bands":[{"id":"missing","min":0,"max":30,"description":"Não há pergunta, ameaça ou estranheza, ou a cena ignora o tema."},{"id":"thin","min":31,"max":75,"description":"O clima é nomeado, mas uma exigência central do tema não entra."},{"id":"working","min":76,"max":120,"description":"A cena cumpre o tema. Uma exigência aparece e pouco altera a tensão."},{"id":"strong","min":121,"max":150,"description":"O contexto do tema é a fonte da pergunta e do que o leitor teme ou desconfia."}]},{"id":"shape","name":"Uma pergunta aberta","kind":"objective","publicDescription":"Sustente uma pergunta que faça o leitor querer continuar.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"Não há pergunta, ou ela é respondida antes de existir."},{"id":"thin","min":41,"max":100,"description":"A pergunta aparece uma vez e a cena segue sem voltar a ela."},{"id":"working","min":101,"max":160,"description":"A pergunta permanece, com um trecho em que a tensão é só afirmada."},{"id":"strong","min":161,"max":200,"description":"Cada novo detalhe complica a pergunta ou a reposiciona. O fim ainda deixa o leitor com ela, ou a transforma de propósito."}]},{"id":"world","name":"Informação controlada","kind":"objective","publicDescription":"Escolha quando revelar pistas e quando guardar informação.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"O texto despeja a explicação, ou esconde tudo sem dar o que notar."},{"id":"thin","min":41,"max":100,"description":"Há pistas, mas elas não se relacionam com o que o leitor já viu."},{"id":"working","min":101,"max":160,"description":"O que é revelado ou retido passa pelo ponto de vista. Uma informação importante chega solta."},{"id":"strong","min":161,"max":200,"description":"Notar, evitar e errar a leitura conduzem a cena. O que o leitor sabe em cada momento parece escolhido."}]},{"id":"people","name":"Aposta humana","kind":"subjective","publicDescription":"Mostre o que alguém pode perder diante do perigo.","maxScore":250,"bands":[{"id":"missing","min":0,"max":50,"description":"Ninguém tem o que perder. Só há atmosfera."},{"id":"thin","min":51,"max":125,"description":"O medo é nomeado e não muda o que a pessoa faz."},{"id":"working","min":126,"max":200,"description":"A pessoa age por causa do que teme, quer ou esconde, com um momento ainda genérico."},{"id":"strong","min":201,"max":250,"description":"A aposta é específica. O leitor entende o que esta pessoa não pode se dar ao luxo de perder."}]},{"id":"prose","name":"Atmosfera na prosa","kind":"subjective","publicDescription":"Use detalhes e ritmo para tornar a ameaça presente.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"Não há mundo sensorial, ou o texto só declara que a cena é tensa."},{"id":"thin","min":41,"max":100,"description":"Os detalhes existem e não selecionam o que deve inquietar."},{"id":"working","min":101,"max":160,"description":"Alguns objetos, sons ou silêncios trabalham. Outros enfeitam."},{"id":"strong","min":161,"max":200,"description":"O que é descrito, repetido ou omitido sustenta a pergunta. A frase tem o tempo do medo ou da suspeita."}]}]'::jsonb WHERE id = 'rubric_suspense';

--> statement-breakpoint
UPDATE rubric SET genre = 'turning_point', criteria = '[{"id":"fidelity","name":"Aderência ao tema","kind":"objective","publicDescription":"Mostre na cena o contexto e as exigências do exercício.","maxScore":150,"bands":[{"id":"missing","min":0,"max":30,"description":"Não há mudança de rumo, ou a cena ignora o tema."},{"id":"thin","min":31,"max":75,"description":"Há uma decisão, mas uma exigência central do tema fica de fora."},{"id":"working","min":76,"max":120,"description":"A cena cumpre o tema. Uma exigência aparece e pouco pesa na escolha."},{"id":"strong","min":121,"max":150,"description":"O contexto do tema é o material da decisão. Sem ele, a virada não existiria."}]},{"id":"shape","name":"Antes e depois","kind":"objective","publicDescription":"Deixe visível o que muda com a decisão.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"Não há momento de mudança nem consequência."},{"id":"thin","min":41,"max":100,"description":"A pessoa declara a decisão, e nada no mundo da cena se altera."},{"id":"working","min":101,"max":160,"description":"Dá para ver o momento e uma consequência. Um dos dois ainda é resumido."},{"id":"strong","min":161,"max":200,"description":"Situação, virada e consequência estão em sequência, e a consequência só faz sentido por causa da virada."}]},{"id":"world","name":"Vida concreta em volta da decisão","kind":"objective","publicDescription":"Dê à decisão um lugar entre objetos, tarefas e relações.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"A cena é opinião ou memória solta, sem lugar nem gesto."},{"id":"thin","min":41,"max":100,"description":"O cômodo é nomeado, mas os objetos não participam da escolha."},{"id":"working","min":101,"max":160,"description":"Pelo menos um objeto ou gesto carrega a decisão. Outro trecho fica abstrato."},{"id":"strong","min":161,"max":200,"description":"O que a pessoa pega, larga, guarda ou não consegue largar é a decisão."}]},{"id":"people","name":"Virada merecida","kind":"subjective","publicDescription":"Prepare a escolha com o que a pessoa vive na cena.","maxScore":250,"bands":[{"id":"missing","min":0,"max":50,"description":"A virada não tem relação com o que a cena mostrou."},{"id":"thin","min":51,"max":125,"description":"A escolha é possível, mas chega por uma explicação, não pelo que a pessoa percebeu."},{"id":"working","min":126,"max":200,"description":"A pressão está plantada e a escolha responde a ela, com um salto ainda abrupto."},{"id":"strong","min":201,"max":250,"description":"O leitor acompanha o custo e entende a escolha, mesmo se faria outra no lugar da personagem."}]},{"id":"prose","name":"Prosa interior","kind":"subjective","publicDescription":"Aproxime o leitor do conflito interior por meio da prosa.","maxScore":200,"bands":[{"id":"missing","min":0,"max":40,"description":"Não há vida interior, ou ela é uma lista de traços."},{"id":"thin","min":41,"max":100,"description":"Os pensamentos são genéricos e poderiam ser de outra pessoa."},{"id":"working","min":101,"max":160,"description":"A voz interior é reconhecível, com uma passagem que explica o que já estava claro."},{"id":"strong","min":161,"max":200,"description":"Pensamento, imagem e omissão têm a voz desta pessoa. O custo fica no jeito de perceber, não num slogan."}]}]'::jsonb WHERE id = 'rubric_turning_point';

--> statement-breakpoint
UPDATE theme SET genre = 'action', objective = 'Treinar movimento e escolhas sob pressão em um espaço instável.', min_words = 400, max_words = 900, briefing = '{"situation":"Chove desde o meio-dia. Duas pessoas adultas estão num telhado, três andares acima de uma rua estreita. Uma delas carrega um envelope que a outra precisa ter antes de amanhecer. Elas não são estranhas: existe uma história entre as duas, e você pode insinuá-la sem explicá-la. O próximo telhado dá para um pulo e também dá para um erro. A escada de incêndio do outro prédio é a única descida que não é o caminho por onde subiram.","alreadyTrue":["Quem está com o envelope não quer entregá-lo.","A outra pessoa é mais rápida no chão plano e pior com altura.","Alguém lá embaixo já as viu e ainda não chegou ao telhado."],"mustInclude":["A travessia de pelo menos duas superfícies diferentes, como telhado, beiral, andaime, escada ou telha.","Um momento em que o plano muda por causa da chuva, do vão ou da pessoa lá embaixo.","O envelope ainda importando no fim, tenha mudado de mãos ou não."],"youDecide":"Quem são essas pessoas, o que há no envelope, se alguém pula, escorrega ou se recusa a pular, e como a cena termina. Fique num ponto de vista ou mude. Não pare antes de alguém ter que escolher.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","O destino do envelope e a decisão de pular ou recusar o salto."]}'::jsonb WHERE id = 'theme_roof_gap';

--> statement-breakpoint
UPDATE theme SET genre = 'action', objective = 'Treinar uma corrida contra o tempo com obstáculos e custos concretos.', min_words = 400, max_words = 900, briefing = '{"situation":"Fim de tarde numa rua cheia. A pessoa que você acompanha tem quatro minutos para chegar a uma esquina onde alguém espera, e essa alguém não fica depois do farol que combinaram. A rua esconde e também atrasa: uma procissão, um caminhão atravessado, um protesto ou uma feira, você escolhe o obstáculo. Uma segunda pessoa adulta tenta impedir a primeira, ou tenta chegar junto. Elas se veem em alguns trechos e se perdem em outros.","alreadyTrue":["Atrasar tem um custo real, e as duas sabem qual é.","Nenhuma das duas pode simplesmente avisar. O telefone está sem bateria, perdido ou é perigoso usar.","O caminho que tinham planejado fechou."],"mustInclude":["Movimento num lugar público, com gente que não faz parte da corrida e mesmo assim atrapalha.","Uma escolha que ganha tempo e custa outra coisa: uma dívida, uma mentira, um objeto ou a confiança de alguém.","Uma chegada, um atraso consumado ou a decisão de parar de correr. A cena precisa pousar numa dessas três."],"youDecide":"A cidade, a relação entre as pessoas, o que significa esperar na esquina e quem corre atrás de quem. O obstáculo pode ser cômico ou ameaçador. Mantenha a cena física.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","Uma chegada, um atraso ou a decisão de parar."]}'::jsonb WHERE id = 'theme_last_blocks';

--> statement-breakpoint
UPDATE theme SET genre = 'fight', objective = 'Treinar causa e efeito físico numa luta em espaço apertado.', min_words = 400, max_words = 900, briefing = '{"situation":"De noite, numa cozinha pequena demais para duas pessoas adultas brigarem. Elas se conhecem bem. Não há espada nem arma de fogo no cômodo. Há bancada, pia, um bloco de facas ou a ausência dele, cadeiras, uma panela ainda quente se você quiser, e uma porta que abre para dentro. Uma delas veio para ir embora. A outra não deixa isso acontecer sem uma resposta. A discussão de palavras já falhou. A cena começa no primeiro empurrão, ou no instante imediatamente anterior.","alreadyTrue":["Elas já brigaram com palavras nesta noite, e isso não mudou nada.","Uma é mais forte. A outra conhece melhor a cozinha.","Pode haver uma terceira pessoa dormindo no cômodo ao lado. Se houver, as duas sabem."],"mustInclude":["Uma luta que use o cômodo. Pelo menos um objeto muda o que alguém consegue fazer.","Dor, cansaço ou hesitação alterando o gesto seguinte.","Uma parada: alguém desiste, não consegue continuar, ou escolhe não desferir o último golpe. Não escreva uma morte, a menos que o peso dela tenha sido construído. A briga pode terminar menor do que isso e ainda assim acabar."],"youDecide":"Quem elas são uma para a outra, do que se trata a partida, e o quanto a violência é feia ou contida. Permaneça dentro do apartamento.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","Uma luta contida e um desfecho sem morte."]}'::jsonb WHERE id = 'theme_narrow_kitchen';

