UPDATE theme SET genre = 'fight', objective = 'Treinar trocas de luta que revelem regras, intenções e consequências.', min_words = 500, max_words = 1000, briefing = '{"situation":"Uma briga marcada, num lugar com regra: um ringue, um pátio, uma academia depois do expediente ou uma clareira aonde as duas pessoas adultas foram de propósito. Há alguns espectadores, uma única pessoa fazendo às vezes de árbitro, ou ninguém. Elas concordaram com isso. Concordar não significa querer a mesma coisa. Uma está ali para vencer limpo. A outra está ali porque perder, ou recusar, custaria mais do que apanhar.","alreadyTrue":["Existe uma regra que as duas conhecem: sem punho fechado, o primeiro a sair do risco, até alguém permanecer no chão, ou um número combinado de trocas.","Uma delas treinou mais.","Algo fora do combate será diferente amanhã conforme o resultado, e as duas sabem o quê."],"mustInclude":["Pelo menos três trocas distintas. A segunda precisa ser diferente por causa da primeira.","Uma quebra da regra, ou um momento em que alguém poderia quebrá-la e decide.","A plateia ou a testemunha, se existir, afetando quem luta. Se não houver ninguém, o silêncio precisa pesar."],"youDecide":"A época, o tipo de luta, a aposta e o resultado. Uma vitória limpa, uma vitória roubada e uma recusa podem encerrar a cena.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","Uma vitória, uma derrota ou a recusa de continuar."]}'::jsonb WHERE id = 'theme_agreed_bout';

