UPDATE theme SET genre = 'romance', objective = 'Treinar aproximação e mudança do vínculo por meio de pequenos gestos.', min_words = 400, max_words = 800, briefing = '{"situation":"A noite deu errado em público: um jantar que desabou, uma festa a que não deviam ter ido, um trem que perderam juntas. Agora duas pessoas adultas estão debaixo de um toldo, ou na boca de uma porta, esperando o tempo passar. Quase se encostam porque o espaço seco é pequeno. Não são um casal resolvido. Podem ter sido, podem estar no começo, ou esta pode ser a única noite. Uma veste o casaco da outra, ou segura o casaco e não o veste.","alreadyTrue":["Algo foi dito mais cedo nesta noite e ainda não teve resposta.","Uma delas tem um lugar para estar. A outra não tem, ou finge que não.","Ninguém vem interromper enquanto a cena durar."],"mustInclude":["Atenção à outra pessoa por um detalhe físico pequeno, não por um discurso sobre sentimento.","Um movimento de aproximação e um de afastamento, em qualquer ordem. O beijo pode acontecer, quase acontecer ou ser recusado.","No fim, uma delas deixa o próximo passo claro, mesmo que a outra não aceite."],"youDecide":"A história entre elas, o que foi dito no jantar ou na festa, e se a cena é terna, engraçada ou áspera. Explicitar é opcional. As duas continuam com vontade própria.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","A aproximação não terminar em casal."]}'::jsonb WHERE id = 'theme_under_the_awning';

