UPDATE theme SET genre = 'romance', objective = 'Treinar intimidade e tensão diante de uma partida próxima.', min_words = 400, max_words = 900, briefing = '{"situation":"Uma cozinha, mais tarde do que as duas pessoas adultas pretendiam ficar acordadas. Uma parte de manhã: outra cidade, uma turnê, um casamento que não é este, um emprego, uma decisão já tomada. A outra lava um único copo, seca, ou não consegue largá-lo. O que elas são uma para a outra não tem um nome arrumado. A casa está quieta. Uma mala já está na porta, ou ainda não foi feita.","alreadyTrue":["A partida é real. A cena não pode cancelá-la com um discurso, a menos que você mostre o custo de ficar e ainda assim escolha.","Elas já se tocaram antes, ou nunca se tocaram. Escolha uma opção e respeite-a.","Há um objeto ordinário na cozinha que pertence às duas, ou que uma está prestes a deixar para trás."],"mustInclude":["Detalhe doméstico usado como intimidade ou como distância.","Algo que quase é dito duas vezes antes de ser dito, ou antes de quem ia dizer escolher o silêncio.","Um fim que muda a manhã, mesmo de leve: uma promessa, uma recusa, uma piada que não é só piada, uma mão que fica ou que solta."],"youDecide":"A relação, o motivo da partida e o quanto elas admitem. A cena pode ser quieta. Quieta ainda precisa de uma virada.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","A partida acontecer ou ser abandonada."]}'::jsonb WHERE id = 'theme_two_am_glass';

