UPDATE theme SET genre = 'dialogue', objective = 'Treinar vozes distintas e subtexto numa conversa sem saída imediata.', min_words = 400, max_words = 900, briefing = '{"situation":"Duas pessoas adultas dentro de um carro. O trânsito parou e não vai abrir antes de elas chegarem ao lugar para onde já estão atrasadas: um balcão de hospital, um jantar de família, a calçada de um aeroporto, uma escola. O assunto que elas vinham evitando cabe nesta viagem e pode não caber depois que descerem. O rádio pode estar ligado. Uma delas pode insistir num caminho alternativo que as duas sabem que não existe.","alreadyTrue":["O trânsito não as coloca em perigo. A pressão é a conversa.","Uma sabe de uma coisa que a outra não sabe, ou as duas sabem e só uma vai dizer.","Sair do carro é possível, e significaria alguma coisa. Pelo menos uma delas considera isso."],"mustInclude":["Diálogo conduzindo a cena. A ação fica limitada ao carro: mãos, retrovisor, buzina, freio de mão, um olhar.","Uma frase que acerta mais forte do que quem falou pretendia.","Uma mudança até o trânsito andar, ou até uma delas decidir que não importa se ele anda."],"youDecide":"Quem são, qual é o segredo ou a acusação, e se chegam ainda se falando. Deixe cada uma soar como ela mesma. Elas podem se interromper.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","O conflito terminar sem acordo."]}'::jsonb WHERE id = 'theme_traffic';

