UPDATE theme SET genre = 'dialogue', objective = 'Treinar uma conversa em que o assunto evitado pressiona cada fala.', min_words = 500, max_words = 1000, briefing = '{"situation":"Depois de um funeral, ou alguns dias depois, duas pessoas adultas que já foram próximas se sentam num lugar em que podem ser ouvidas se não tiverem cuidado: a cozinha durante a recepção, um corredor de escada, o estacionamento, um banco lá fora. Todo o resto fala de quem morreu. Estas duas falam em volta. Têm uma conta antiga, mais velha do que a morte, e a morte tornou mais grosseiro continuar ignorando.","alreadyTrue":["Elas amaram, ou falharam, a mesma pessoa de jeitos diferentes.","Existe uma história sobre quem morreu em que elas não concordam.","Esta é a primeira vez que ficam a sós desde antes da morte."],"mustInclude":["Uma conversa que circula e, uma vez, para de circular.","Uma memória concreta de quem morreu, usada para defender, acusar ou consolar: um lugar, um objeto, uma frase que essa pessoa dizia.","Uma delas pede alguma coisa. A outra responde, mesmo que a resposta seja não."],"youDecide":"A relação, como a pessoa morreu e o quanto elas conseguem ser honestas. Doença, acidente ou velhice bastam. A cena não precisa reconciliá-las. Não descreva a violência da morte.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","O funeral permanecer fora da cena."]}'::jsonb WHERE id = 'theme_everything_but_the_dead';

