UPDATE theme SET genre = 'suspense', objective = 'Treinar pistas e controle de informação diante de uma ameaça incerta.', min_words = 400, max_words = 900, briefing = '{"situation":"Uma pessoa adulta chega em casa, ou de volta a um quarto que conhece, e uma luz está acesa que ela apagou. Nada parece ter sumido. O lugar é ordinário: um apartamento, a casa da infância, um quarto de hotel em que ela já dormiu. É tarde. Ela pode ir embora, chamar alguém ou entrar mais. A cena começa na porta.","alreadyTrue":["Ela tem certeza de que apagou aquela luz. Leve essa certeza a sério, e deixe também que ela possa estar errada.","Há um som que não pertence ao lugar, e ele pode ter uma causa ordinária.","Alguém de quem ela gosta está lá dentro, deve chegar mais tarde, ou não faz parte desta noite. Escolha, e não traga um resgate de fora da cena."],"mustInclude":["Uma leitura lenta do cômodo. Um objeto comum pode estar errado por um palmo.","Um momento em que a explicação da personagem falha, ou quase funciona.","Um fim que responde a um medo e deixa outro aberto. Você não precisa mostrar o que, se é que havia algo, estava no quarto."],"youDecide":"Se há mais alguém, se a ameaça é humana e o quanto a personagem confia na própria memória. O mal-estar pode continuar quieto.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","O mistério permanecer sem solução."]}'::jsonb WHERE id = 'theme_light_left_on';

