UPDATE theme SET genre = 'suspense', objective = 'Treinar suspense usando o espaço conhecido e uma aposta humana.', min_words = 500, max_words = 1000, briefing = '{"situation":"Duas pessoas adultas estão dentro de uma casa. Uma mora ali ou cresceu ali. A outra não devia estar dentro. O ponto de vista pode ser de qualquer uma das duas. A casa tem uma planta que o leitor deve aprender pelo movimento: qual porta emperra, qual degrau reclama, onde o interruptor não está. Está escuro o bastante para o conhecimento da casa valer mais do que a força.","alreadyTrue":["Quem entrou sem direito quer uma coisa específica: um objeto, uma pessoa, um cômodo ou uma saída. Escolha uma.","Quem conhece a casa não sabe, durante a maior parte da cena, onde a outra está.","O telefone não serve, está fora de alcance ou já é um risco."],"mustInclude":["Movimento que dependa de quem conhece os cômodos.","Um erro de quem deveria ter a vantagem.","Um quase encontro, ou um encontro, que mude quem está caçando. Você não precisa escrever uma captura nem uma fuga se a virada em si pousar."],"youDecide":"Por que a pessoa entrou, se elas se conhecem e o quanto a cena se torna violenta. A suspeita pode trabalhar tanto quanto a corrida.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","A ameaça não se revelar por completo."]}'::jsonb WHERE id = 'theme_knows_the_house';

