UPDATE theme SET genre = 'turning_point', objective = 'Treinar uma decisão interior por meio de objetos e ações concretas.', min_words = 400, max_words = 800, briefing = '{"situation":"Uma pessoa adulta faz, desfaz ou refaz uma mala em cima de uma cama, no chão ou numa cadeira. Ela devia partir em breve: hoje, hoje à noite, ou dentro de uma hora. O motivo é prático e também não é. Alguma coisa no quarto continua sendo pegada e devolvida ao lugar. Ninguém mais precisa estar presente. Se houver alguém na porta, essa pessoa não decide.","alreadyTrue":["Uma passagem, uma chave, um emprego ou uma pessoa está esperando, e perder essa chance tem custo.","Há um objeto que não pertence a quem viaja, ou que essa pessoa nunca deveria levar.","A mala já foi feita uma vez. Esta é a segunda."],"mustInclude":["A decisão acontecendo pelo que entra na mala e pelo que fica.","Uma memória só se ela mudar o que as mãos fazem em seguida.","Um fim em que a pessoa parte, fica ou para na porta. O leitor precisa saber qual foi a escolha e o que ela custou, sem um discurso que explique o tema."],"youDecide":"Para onde ela iria, o que está deixando e se a escolha é corajosa, egoísta ou as duas coisas. Permaneça neste quarto.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","A decisão ser pequena ou ambígua."]}'::jsonb WHERE id = 'theme_what_stays_in_the_bag';

