UPDATE theme SET genre = 'turning_point', objective = 'Treinar uma virada de relação sustentada por uma escolha visível.', min_words = 400, max_words = 900, briefing = '{"situation":"Uma chave está numa mesa entre duas pessoas adultas, ou entre uma pessoa e uma cadeira vazia. Ela abre um lugar que foi das duas: um apartamento, um ateliê, um carro, um portão. Uma veio devolvê-la. Devolver era para ser simples. A outra coisa que veio dizer, ou evitar dizer, não cabe no mesmo minuto. É de dia. A cena deve parecer ordinária até deixar de ser.","alreadyTrue":["A relação já mudou antes desta cena. A chave está atrasada.","Uma delas aceitaria a chave de volta se fosse oferecida. A outra não tem certeza de que quer isso.","Além da chave, há uma tarefa ou um objeto pequeno, como correspondência, uma planta ou um casaco, que dá às mãos o que fazer."],"mustInclude":["A chave sendo tocada, movida ou deixada quieta de um jeito que o leitor veja.","Uma frase que não dá para desdizer, ou uma frase que alguém chega a formular e troca por uma menor.","Uma escolha sobre a chave que combine com a escolha sobre a pessoa. Elas só podem divergir se a cena mostrar a contradição de propósito."],"youDecide":"O que elas foram uma para a outra, quem terminou e se a chave muda de mãos. Reconciliação é possível. Uma despedida limpa e pouco gentil também. Sustente a que você escolher.","doNotPenalize":["Um final triste, aberto ou sem vitória.","Escolhas de estilo e de ponto de vista que sirvam à cena.","A relação não recomeçar."]}'::jsonb WHERE id = 'theme_key_on_the_table';

