CREATE OR REPLACE FUNCTION valid_rubric_criteria(criteria jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE c jsonb; b jsonb; total integer := 0; next_min integer; band_index integer; ids text[] := '{}';
BEGIN
  IF jsonb_typeof(criteria) <> 'array' OR jsonb_array_length(criteria) <> 5 THEN RETURN false; END IF;
  FOR c IN SELECT value FROM jsonb_array_elements(criteria) LOOP
    IF jsonb_typeof(c->'id') IS DISTINCT FROM 'string' OR jsonb_typeof(c->'name') IS DISTINCT FROM 'string' OR jsonb_typeof(c->'publicDescription') IS DISTINCT FROM 'string' OR coalesce(c->>'id', '') = '' OR c->>'id' = ANY(ids) OR coalesce(c->>'name', '') = ''
      OR coalesce(c->>'publicDescription', '') = '' OR coalesce(c->>'kind', '') NOT IN ('objective','subjective')
      OR jsonb_typeof(c->'maxScore') IS DISTINCT FROM 'number' OR (c->>'maxScore')::numeric <> trunc((c->>'maxScore')::numeric)
      OR (c->>'maxScore')::integer <= 0 OR jsonb_typeof(c->'bands') IS DISTINCT FROM 'array' OR jsonb_array_length(c->'bands') <> 4 THEN RETURN false; END IF;
    ids := array_append(ids, c->>'id'); total := total + (c->>'maxScore')::integer;
    next_min := 0; band_index := 1;
    FOR b IN SELECT value FROM jsonb_array_elements(c->'bands') LOOP
      IF b->>'id' IS DISTINCT FROM (ARRAY['missing','thin','working','strong'])[band_index]
        OR jsonb_typeof(b->'min') IS DISTINCT FROM 'number' OR jsonb_typeof(b->'max') IS DISTINCT FROM 'number'
        OR (b->>'min')::numeric <> next_min OR (b->>'max')::numeric <> trunc((b->>'max')::numeric)
        OR (b->>'max')::integer < next_min OR jsonb_typeof(b->'description') IS DISTINCT FROM 'string' OR coalesce(b->>'description', '') = '' THEN RETURN false; END IF;
      next_min := (b->>'max')::integer + 1; band_index := band_index + 1;
    END LOOP;
    IF next_min <> (c->>'maxScore')::integer + 1 THEN RETURN false; END IF;
  END LOOP;
  RETURN total = 1000;
EXCEPTION WHEN OTHERS THEN RETURN false;
END; $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION valid_briefing(briefing jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE k text; item jsonb;
BEGIN
  IF jsonb_typeof(briefing) <> 'object' THEN RETURN false; END IF;
  FOREACH k IN ARRAY ARRAY['situation','youDecide'] LOOP
    IF jsonb_typeof(briefing->k) IS DISTINCT FROM 'string' OR length(trim(briefing->>k)) = 0 THEN RETURN false; END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['alreadyTrue','mustInclude','doNotPenalize'] LOOP
    IF jsonb_typeof(briefing->k) IS DISTINCT FROM 'array' OR jsonb_array_length(briefing->k) = 0 THEN RETURN false; END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(briefing->k) LOOP
      IF jsonb_typeof(item) <> 'string' OR length(trim(item #>> '{}')) = 0 THEN RETURN false; END IF;
    END LOOP;
  END LOOP;
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END; $$;
