CREATE OR REPLACE FUNCTION enforce_theme_genre() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.genre IS NOT NULL AND NOT EXISTS (SELECT 1 FROM rubric WHERE id = NEW.rubric_id AND genre = NEW.genre) THEN
    RAISE EXCEPTION 'Theme genre must match rubric genre' USING ERRCODE = '23514', CONSTRAINT = 'theme_rubric_genre';
  END IF;
  RETURN NEW;
END; $$;
--> statement-breakpoint
CREATE TRIGGER theme_rubric_genre BEFORE INSERT OR UPDATE OF genre, rubric_id ON theme FOR EACH ROW EXECUTE FUNCTION enforce_theme_genre();
--> statement-breakpoint
CREATE OR REPLACE FUNCTION enforce_rubric_genre() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM theme WHERE rubric_id = NEW.id AND genre IS NOT NULL AND genre IS DISTINCT FROM NEW.genre) THEN
    RAISE EXCEPTION 'Rubric genre must match linked exercises' USING ERRCODE = '23514', CONSTRAINT = 'rubric_theme_genre';
  END IF;
  RETURN NEW;
END; $$;
